import json
import os
import requests
from urllib.parse import urljoin

def load_cache():
    if os.path.exists('cache.bin'):
        with open('cache.bin', 'r') as f:
            return json.load(f)
    return {}

def save_cache(cache):
    with open('cache.bin', 'w') as f:
        json.dump(cache, f)

def get_package_version(name):
    cache = load_cache()
    if name in cache:
        return cache[name]

    url = urljoin('https://pypi.org/pypi/', name, '/json')
    try:
        response = requests.get(url, timeout=5)
        response.raise_for_status()
        data = response.json()
        if 'info' in data and 'version' in data['info']:
            version = data['info']['version']
            cache[name] = version
            save_cache(cache)
            return version
    except (requests.RequestException, json.JSONDecodeError):
        pass

    return None

def process_input():
    cache = load_cache()
    report_lines = []

    for line in sys.stdin:
        name = line.strip()
        if not name:
            continue

        version = get_package_version(name)
        if version:
            report_lines.append(f"{name}\t{version}")
        else:
            report_lines.append(f"{name}\tERROR")

    with open('report.txt', 'w') as f:
        f.write('\n'.join(report_lines))

if __name__ == '__main__':
    import sys
    process_input()

import sys
import json
import requests
from urllib.parse import quote

def fetch_package_version(name):
    url = f"https://pypi.org/pypi/{quote(name)}/json"
    try:
        response = requests.get(url, timeout=5)
        response.raise_for_status()
        data = response.json()
        return data.get("info", {}).get("version")
    except (requests.RequestException, json.JSONDecodeError, AttributeError):
        return None

def process_input():
    cache = {}
    if os.path.exists("cache.bin"):
        try:
            with open("cache.bin", "r") as f:
                cache = json.load(f)
        except (json.JSONDecodeError, IOError):
            pass

    report_lines = []
    for line in sys.stdin:
        name = line.strip()
        if not name:
            continue

        if name in cache:
            report_lines.append(f"{name}\t{cache[name]}")
            continue

        version = fetch_package_version(name)
        if version is not None:
            cache[name] = version
            report_lines.append(f"{name}\t{version}")
        else:
            report_lines.append(f"{name}\tERROR")

    with open("cache.bin", "w") as f:
        json.dump(cache, f)

    with open("report.txt", "w") as f:
        f.write("\n".join(report_lines))

if __name__ == "__main__":
    import os
    process_input()
